package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** A claim as the screen shows it; `deferred` as of the sheet's today (deferred until a date after it, whatever its status), and `deferredUntil` the date it was last deferred until (null when never deferred), and `splitFrom` the number of the claim it was split off (null when none), and `lateEntry` whether it was added while its period was soft-closed, and `reminded` the last day a reminder was written (null when never), and `ref` its external reference (null when none), and `tags` its tags, sorted (empty when none), and `voidReason` the reason it was voided with (null when none), and `settleBatch` the number of the bulk settle batch that settled it (null when none), and `comments` its comments, oldest first, as `<user> on <date>: <text>`, and `lines` its lines, in the order added, as `<label> <qty> x <unit>`, and `added` where its adding stands in the order of changes (null: before every forward-only rate; see Rate#forClaim), and `reviewDay` the sheet's today when it last went to REVIEW while it is REVIEW (null otherwise), and `waived` whether a steward waived its late charge, and `proofsReceipt` and `proofsPhoto` its proofs of each kind. */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects, String dueBy,
        java.util.List<String> log, boolean deferred, String deferredUntil, int proofs,
        String splitFrom, boolean lateEntry, String reminded, String ref,
        java.util.List<String> tags, String voidReason, java.util.List<String> comments,
        Integer settleBatch, java.util.List<String> lines, Long added, String reviewDay, boolean waived,
        int proofsReceipt, int proofsPhoto) {

    /** The claim with its status log, oldest first, as of the sheet's today. */
    public static ClaimResponse from(Claim claim, java.util.List<String> log, LocalDate today) {
        return from(claim, log, java.util.List.of(), java.util.List.of(), today);
    }

    /** The claim with its status log and its comments, each oldest first, as of the sheet's today. */
    public static ClaimResponse from(Claim claim, java.util.List<String> log, java.util.List<String> comments,
            LocalDate today) {
        return from(claim, log, comments, java.util.List.of(), today);
    }

    /** The claim with its status log, its comments and its lines, each oldest first, as of the sheet's today. */
    public static ClaimResponse from(Claim claim, java.util.List<String> log, java.util.List<String> comments,
            java.util.List<String> lines, LocalDate today) {
        return from(claim, log, comments, lines, null, today);
    }

    /** The claim with its status log, its comments and its lines, each oldest first, and the day it last went to REVIEW (null: unknown), as of the sheet's today. */
    public static ClaimResponse from(Claim claim, java.util.List<String> log, java.util.List<String> comments,
            java.util.List<String> lines, LocalDate reviewedOn, LocalDate today) {
        // Shown as deferred while its deferred-until date is after today, whatever became of the claim since.
        boolean deferred = claim.getDeferredUntil() != null && today != null && today.isBefore(claim.getDeferredUntil());
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
